abstract class Forma
{
    public abstract int Area();

    public string Mostrar()
    {
        return "Area " + Area();
    }
}

interface IImprimivel
{
    string Imprimir();
}

class Quadrado : Forma, IImprimivel
{
    public override int Area()
    {
        return 4;
    }

    public string Imprimir()
    {
        return Mostrar();
    }
}

