abstract class Shape
{
    public abstract int Area();

    public string Show()
    {
        return "Area " + Area();
    }
}

interface IPrintable
{
    string Print();
}

class Square : Shape, IPrintable
{
    public override int Area()
    {
        return 4;
    }

    public string Print()
    {
        return Show();
    }
}

example:
abstract class Potion
{
    public abstract int Dose();

    public string Label()
    {
        return "Dose " + Dose();
    }
}

class Elixir : Potion
{
    public override int Dose()
    {
        return 3;
    }
}

interface IPoisonous
{
    int Danger();
}

class Venom : IPoisonous
{
    public int Danger()
    {
        return 9;
    }
}

class Shelf
{
    public string Describe()
    {
        Potion potion = new Elixir();
        IPoisonous poison = new Venom();
        return potion.Label() + " / danger " + poison.Danger();
    }
}
